"""Write replay: every write packet the vendor page sent must be regenerated byte for byte
by our builders from its decoded meaning (tests/fixtures/vendor_writes09.json)."""
import json
import unittest

from cx68 import policy
from cx68 import protocol as P

from fakes import FIXTURES

WRITES = [bytes.fromhex(h) for h in json.loads((FIXTURES / "vendor_writes09.json").read_text())["writes"]]


def batches():
    """Group consecutive 0x65 packets into (param, raw array, last flag) runs."""
    run, out = [], []
    for pkt in WRITES:
        if pkt[0] != 0x65:
            continue
        if run and (pkt[1] != run[0][1] or pkt[3] == 0):
            out.append(run)
            run = []
        run.append(pkt)
    if run:
        out.append(run)
    return out


class WriteReplayTest(unittest.TestCase):
    def test_magnetism_writes_rebuild_byte_for_byte(self):
        groups = batches()
        self.assertGreaterEqual(len(groups), 7)
        for run in groups:
            param = run[0][1]
            size = 128 if param == P.Param.KEY_MODE else 256
            raw = b"".join(p[8:64] for p in run)[:size]
            last = bool(run[-1][4])
            rebuilt = [policy.encode(c.msg, c.checksum) for c in P.set_magnetism_array(param, raw, last)]
            with self.subTest(param=param, pages=len(run)):
                self.assertEqual(rebuilt, run)

    def test_key_mode_write_rebuilds(self):
        mode_pkts = [p for p in WRITES if p[0] == 0x1D]
        self.assertEqual(mode_pkts, [policy.encode(P.set_key_mode("custom").msg, policy.BIT7)])

    def test_decoded_meaning(self):
        groups = {(run[0][1], i): run for i, run in enumerate(batches())}
        actuation = [run for (param, _), run in groups.items() if param == 0]
        w = [P.u16_slots([b"".join(p[8:64] for p in run)[:256]])[14] for run in actuation]
        self.assertEqual(w, [150, 200])            # W set to 1.50 mm, then back to 2.00 mm
        rt = next(run for (param, _), run in groups.items() if param == 2)
        self.assertEqual(P.u16_slots([b"".join(p[8:64] for p in rt)[:256]])[14], 20)  # 0.20 mm
        w_modes = [b"".join(p[8:64] for p in run)[14] for (param, _), run in sorted(groups.items(), key=lambda x: x[0][1])
                   if param == P.Param.KEY_MODE]
        self.assertEqual(w_modes, [0x00, 0x80, 0x00])  # RT off, on (bit 7), off again
        self.assertTrue(P.key_mode_byte(0x80)["rapid_trigger"])

    def test_writes_refused_without_approval(self):
        for pkt in WRITES:
            self.assertIsNotNone(policy.check(pkt, "readonly", policy.BIT7))
            self.assertIsNone(policy.check(pkt, "readonly", policy.BIT7, policy.validate_allow_writes([0x65, 0x1D])))


if __name__ == "__main__":
    unittest.main()
